self.KB_CONTENT["card:754297"]={"id":"card:754297","ty":"card","sourceId":"754297","title":"『預算管理啟動/取消作業』的作業目的為何？","ver":"iGP","topic":"進行","keywords":["進行","預算","透過","啟動"],"y":"explain","answer":"如欲進行預算管理，可透過此作業啟動預算管理；後續也可透過此作業取消預算的管理。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
